package org.joda.time;

import java.io.*;
import java.io.IOException;
import java.io.ObjectInputStream;
import java.io.ObjectOutputStream;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.Locale;
import org.joda.convert.FromString;
import org.joda.convert.ToString;
import org.joda.time.base.BaseDateTime;
import org.joda.time.chrono.ISOChronology;
import org.joda.time.field.AbstractReadableInstantFieldProperty;
import org.joda.time.field.FieldUtils;
import org.joda.time.format.DateTimeFormatter;
import org.joda.time.format.ISODateTimeFormat;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class MutableDateTime_addMonths_TriageGen2Test {

    @Test
    public void testAddMonthsPositive() {
        // Test adding a positive number of months
        MutableDateTime dt = new MutableDateTime(2023, 1, 15, 10, 0, 0, 0);
        dt.addMonths(3);
        assertEquals(2023, dt.getYear());
        assertEquals(4, dt.getMonthOfYear());
        assertEquals(15, dt.getDayOfMonth());
    }

    @Test
    public void testAddMonthsNegative() {
        // Test adding a negative number of months (subtracting)
        MutableDateTime dt = new MutableDateTime(2023, 5, 15, 10, 0, 0, 0);
        dt.addMonths(-2);
        assertEquals(2023, dt.getYear());
        assertEquals(3, dt.getMonthOfYear());
        assertEquals(15, dt.getDayOfMonth());
    }

    @Test
    public void testAddMonthsZero() {
        // Test adding zero months
        MutableDateTime dt = new MutableDateTime(2023, 1, 15, 10, 0, 0, 0);
        dt.addMonths(0);
        assertEquals(2023, dt.getYear());
        assertEquals(1, dt.getMonthOfYear());
        assertEquals(15, dt.getDayOfMonth());
    }

    @Test
    public void testAddMonthsYearBoundary() {
        // Test crossing year boundary
        MutableDateTime dt = new MutableDateTime(2023, 11, 1, 10, 0, 0, 0);
        dt.addMonths(3);
        assertEquals(2024, dt.getYear());
        assertEquals(2, dt.getMonthOfYear());
    }

    @Test
    public void testAddMonthsEndOfMonthEdgeCase() {
        // Test behavior when adding months results in a different day count (e.g., Jan 31 + 1 month -> Feb 28/29)
        // Joda-Time typically handles this by clamping to the last valid day of the month
        MutableDateTime dt = new MutableDateTime(2023, 1, 31, 10, 0, 0, 0);
        dt.addMonths(1);
        assertEquals(2023, dt.getYear());
        assertEquals(2, dt.getMonthOfYear());
        assertEquals(28, dt.getDayOfMonth());
    }

    @Test
    public void testAddMonthsLeapYear() {
        // Test leap year transition
        MutableDateTime dt = new MutableDateTime(2024, 1, 31, 10, 0, 0, 0);
        dt.addMonths(1);
        assertEquals(2024, dt.getYear());
        assertEquals(2, dt.getMonthOfYear());
        assertEquals(29, dt.getDayOfMonth());
    }

    @Test
    public void testAddMonthsLargeValue() {
        // Test adding a very large number of months
        MutableDateTime dt = new MutableDateTime(2023, 1, 1, 10, 0, 0, 0);
        dt.addMonths(1200); // 100 years
        assertEquals(2123, dt.getYear());
        assertEquals(1, dt.getMonthOfYear());
    }
}
